(() => {
  'use strict';
  const places = window.VIETNAM_PLACES;
  const icons = { coast:'◉', mountain:'△', city:'▦', nature:'❋', history:'⌂' };
  // Image-space anchors: the supplied artwork is stylized, not a geographic projection.
  const anchors = {'sapa':[23,11],'hanoi':[37,18],'ha-long':[51,16],'phong-nha':[36,34],'hue':[46,41],'da-nang':[53,45],'hoi-an':[55,48],'my-son':[48,49],'nha-trang':[64,62],'da-lat':[54,65],'can-tho':[36,77],'phu-quoc':[21,72]};
  const $ = id => document.getElementById(id);
  const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalize = value => value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
  function read(key) { try { const x=JSON.parse(localStorage.getItem(key)||'[]'); return Array.isArray(x)?[...new Set(x.filter(id=>places.some(p=>p.id===id)))]:[]; } catch {return [];} }
  const state={query:'',category:'all',region:'Tất cả',saved:read('vne-favorites'),trip:read('vivu-trip'),savedOnly:false,view:'map',zoom:1,selected:places.some(p=>p.id===location.hash.slice(1))?location.hash.slice(1):'da-lat'};
  document.body.innerHTML = `<header><a class="brand" href="./"><span class="brand-icon" aria-hidden="true">⌁</span><span><b>Vi vu đó đây</b><small>Một Việt Nam, nhiều điều để khám phá</small></span></a><div class="header-actions"><button id="savedToggle" aria-pressed="false">♡ Đã lưu <span id="savedCount"></span></button><button class="primary" id="openTrip">Hành trình <span id="tripCount"></span></button></div></header><main class="layout" id="layout"><aside class="sidebar"><p class="kicker">Khám phá Việt Nam</p><h1>Bạn muốn đi đâu?</h1><p class="muted">Chọn một nơi. Bắt đầu chuyến đi.</p><div class="search"><input type="search" id="search" aria-label="Tìm địa điểm" placeholder="Thử “Da Lat”, “biển”, “phố cổ”…"><button id="clearSearch" aria-label="Xóa tìm kiếm">×</button></div><label for="region">Khu vực</label><select id="region">${window.VIETNAM_REGIONS.map(r=>`<option>${r}</option>`).join('')}</select><div class="chips" id="categories">${window.VIETNAM_CATEGORIES.map(c=>`<button data-category="${c.key}" aria-pressed="${c.key==='all'}">${c.label}</button>`).join('')}</div><div class="row"><button id="viewToggle">Xem danh sách</button><button class="link-button" id="resetFilters">Đặt lại bộ lọc</button></div><div class="results-head"><span id="resultCount" role="status"></span><small>Chọn để khám phá</small></div><div class="results" id="results"></div></aside><section class="map-section" aria-label="Bản đồ địa điểm"><div class="toolbar"><strong>Việt Nam qua từng điểm đến</strong><div class="map-controls"><button id="zoomOut" aria-label="Thu nhỏ">−</button><button id="zoomReset" aria-label="Đặt lại độ phóng">100%</button><button id="zoomIn" aria-label="Phóng to">+</button></div></div><div class="map-window" id="mapWindow"><div class="map-scene" id="scene"><img src="./MAP.png" width="1024" height="1536" alt="Bản đồ minh họa Việt Nam" draggable="false"><div id="markers"></div></div></div><p class="map-note">Bản đồ minh họa · Vị trí trên ảnh mang tính tương đối. Chọn “Chỉ đường” để xem vị trí địa lý trên Google Maps.</p></section><aside class="details" id="details" aria-label="Thông tin địa điểm"></aside></main><dialog id="tripDialog" aria-labelledby="tripTitle"><div class="dialog-head"><div><p class="kicker">Chuyến đi của bạn</p><h2 id="tripTitle">Những điểm muốn ghé</h2></div><button id="closeTrip" aria-label="Đóng hành trình">×</button></div><p class="muted">Thêm địa điểm và sắp xếp theo thứ tự bạn muốn đi.</p><div id="tripContent"></div><p class="tip">Yêu thích và hành trình được lưu trên trình duyệt này. Xuất danh sách để giữ một bản riêng.</p></dialog><div class="toast" id="notice" role="status"></div>`;
  function notify(message){$('notice').textContent=message;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('notice').textContent='',3000);}
  function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{notify('Trình duyệt không cho lưu. Bạn có thể xuất hành trình để giữ lại.');}}
  function visible(){return places.filter(p=>(!state.savedOnly||state.saved.includes(p.id))&&(state.category==='all'||p.categoryKey===state.category)&&(state.region==='Tất cả'||p.region===state.region)&&normalize([p.name,p.region,p.province,...p.tags].join(' ')).includes(normalize(state.query.trim())));}
  function render(){
    const list=visible();
    $('savedCount').textContent=state.saved.length; $('tripCount').textContent=state.trip.length;
    $('savedToggle').setAttribute('aria-pressed',state.savedOnly);
    $('resultCount').textContent=`${list.length} địa điểm${state.savedOnly?' đã lưu':''}`;
    $('results').innerHTML=list.length?list.map(p=>`<button class="result ${p.id===state.selected?'selected':''}" data-select="${p.id}" aria-pressed="${p.id===state.selected}"><span class="symbol" aria-hidden="true">${icons[p.categoryKey]}</span><span><strong>${esc(p.name)}</strong><small>${p.region} · ${p.category}</small></span><span class="chevron" aria-hidden="true">›</span></button>`).join(''):`<div class="empty">${state.savedOnly?'Chưa có địa điểm đã lưu phù hợp.':'Không tìm thấy địa điểm phù hợp.'}<br>Thử từ khóa khác hoặc đặt lại bộ lọc.</div>`;
    $('markers').innerHTML=list.map(p=>{const [x,y]=anchors[p.id];return `<button class="marker ${p.id===state.selected?'selected':''}" data-select="${p.id}" data-side="${['my-son','hue','sapa','can-tho','phu-quoc'].includes(p.id)?'left':p.id==='hoi-an'?'below':'right'}" style="left:${x}%;top:${y}%" aria-label="Khám phá ${esc(p.name)}" aria-pressed="${p.id===state.selected}"><span>${esc(p.name)}</span></button>`;}).join('');
    const p=places.find(p=>p.id===state.selected);
    if(!p){$('details').innerHTML='<div class="empty">Chọn một địa điểm để xem thông tin.</div>';return;}
    const {latitude,longitude}=p.coordinates;
    $('details').innerHTML=`<p class="kicker">Điểm đến của bạn</p><span class="category">${p.region} · ${p.category}</span><h2>${esc(p.name)}</h2><p class="lead">${esc(p.short)}</p><p class="muted">${esc(p.description)}</p><dl class="facts"><dt>Thời điểm gợi ý</dt><dd>${esc(p.season)}</dd><dt>Tọa độ tham khảo</dt><dd>${latitude.toFixed(4)}°N, ${longitude.toFixed(4)}°E</dd></dl><div class="detail-actions"><button class="primary" data-add="${p.id}" ${state.trip.includes(p.id)?'disabled':''}>${state.trip.includes(p.id)?'✓ Đã có trong hành trình':'+ Thêm vào hành trình'}</button><button data-save="${p.id}" aria-pressed="${state.saved.includes(p.id)}">${state.saved.includes(p.id)?'♥ Đã lưu địa điểm':'♡ Lưu địa điểm'}</button><a href="https://www.google.com/maps/dir/?api=1&destination=${latitude},${longitude}" target="_blank" rel="noopener noreferrer">Chỉ đường ↗</a><button id="sharePlace">Sao chép liên kết</button></div><div class="tags">${p.tags.map(t=>`<span>#${esc(t)}</span>`).join('')}</div><p class="tip">Chọn thêm những nơi bạn thích, rồi mở “Hành trình” để sắp xếp chuyến đi.</p>`;
    $('sharePlace').onclick=async()=>{try{const url=new URL(location.href);url.hash=p.id;await navigator.clipboard.writeText(url.href);notify('Đã sao chép liên kết địa điểm');}catch{notify('Không thể sao chép tự động. Bạn có thể sao chép URL trên thanh địa chỉ.');}};
  }
  function select(id){state.selected=id;history.replaceState(null,'',`#${id}`);render();if(matchMedia('(max-width:1100px)').matches)$('details').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});}
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.select)select(b.dataset.select);if(b.dataset.save){const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist('vne-favorites',state.saved);render();}if(b.dataset.add){if(!state.trip.includes(b.dataset.add))state.trip.push(b.dataset.add);persist('vivu-trip',state.trip);render();notify('Đã thêm vào hành trình');}if(b.dataset.category){state.category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',x===b));render();}});
  $('search').oninput=e=>{state.query=e.target.value;render();};$('clearSearch').onclick=()=>{state.query='';$('search').value='';render();$('search').focus();};$('region').onchange=e=>{state.region=e.target.value;render();};
  $('resetFilters').onclick=()=>{state.query='';state.category='all';state.region='Tất cả';state.savedOnly=false;$('search').value='';$('region').value='Tất cả';document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category==='all'));render();};
  $('savedToggle').onclick=()=>{state.savedOnly=!state.savedOnly;render();};
  $('viewToggle').onclick=()=>{state.view=state.view==='map'?'list':'map';$('layout').classList.toggle('list-mode',state.view==='list');$('viewToggle').textContent=state.view==='map'?'Xem danh sách':'Xem bản đồ';};
  function zoom(delta){state.zoom=Math.max(1,Math.min(2,state.zoom+delta));$('scene').style.width=`${state.zoom*100}%`;$('scene').style.maxWidth='none';$('scene').style.flexShrink='0';$('zoomReset').textContent=`${Math.round(state.zoom*100)}%`;$('zoomOut').disabled=state.zoom===1;$('zoomIn').disabled=state.zoom===2;}
  $('zoomIn').onclick=()=>zoom(.25);$('zoomOut').onclick=()=>zoom(-.25);$('zoomReset').onclick=()=>{state.zoom=1;zoom(0);$('mapWindow').scrollTo(0,0);};
  function renderTrip(){
    $('tripContent').innerHTML=state.trip.length?`<ol class="trip-list">${state.trip.map((id,i)=>{const p=places.find(p=>p.id===id);return `<li><div><strong>${i+1}. ${esc(p.name)}</strong><small>${p.region}</small></div><div class="row"><button data-move="${i}" data-step="-1" aria-label="Đưa ${esc(p.name)} lên" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-step="1" aria-label="Đưa ${esc(p.name)} xuống" ${i===state.trip.length-1?'disabled':''}>↓</button><button data-remove="${id}" aria-label="Bỏ ${esc(p.name)}">×</button></div></li>`;}).join('')}</ol><div class="trip-footer"><button id="exportTrip" class="primary">Xuất hành trình (.txt)</button></div>`:`<div class="empty">Hành trình đang trống.<br>Chọn địa điểm và nhấn “Thêm vào hành trình”.</div><button id="sampleTrip">Thêm gợi ý: Huế → Đà Nẵng → Hội An → Mỹ Sơn</button>`;
    $('sampleTrip')?.addEventListener('click',()=>{state.trip=['hue','da-nang','hoi-an','my-son'];saveTrip();});
    $('exportTrip')?.addEventListener('click',()=>{const text='VI VU ĐÓ ĐÂY — HÀNH TRÌNH\n\n'+state.trip.map((id,i)=>{const p=places.find(p=>p.id===id);return `${i+1}. ${p.name}\n${p.short}\nThời điểm: ${p.season}\nhttps://www.google.com/maps/search/?api=1&query=${p.coordinates.latitude},${p.coordinates.longitude}\n`;}).join('\n');const url=URL.createObjectURL(new Blob(['\ufeff',text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='hanh-trinh-vivu.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Đã xuất hành trình');});
  }
  function saveTrip(){persist('vivu-trip',state.trip);render();renderTrip();}
  $('tripContent').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.remove){state.trip=state.trip.filter(id=>id!==b.dataset.remove);saveTrip();}if(b.dataset.move!==undefined){const i=Number(b.dataset.move),j=i+Number(b.dataset.step);if(j>=0&&j<state.trip.length){[state.trip[i],state.trip[j]]=[state.trip[j],state.trip[i]];saveTrip();}}};
  $('openTrip').onclick=()=>{renderTrip();$('tripDialog').showModal();};$('closeTrip').onclick=()=>$('tripDialog').close();
  addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(places.some(p=>p.id===id)){state.selected=id;render();}});
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('tripDialog').open){e.preventDefault();$('search').focus();}});
  render();$('zoomOut').disabled=true;
})();
